  if (isCreateOp) {
    expect(request.body.variables).to.include({
      bankName: 'Random Bank',
      routingNumber: '875946254',
      accountNumber: '97584695365'
    });
    request.reply({
      statusCode: 200,
      body: {
        "data": {
